arguments.file_text:
@page "/catalog"
@using sv_036148edf6b541d49e20ea38f5745826.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-layout">
    <aside class="catalog-sidebar">
        <h3>Filters</h3>

        <div class="filter-section">
            <h4>Categories</h4>
            @if (categories is not null)
            {
                @foreach (var category in categories)
                {
                    <label class="filter-checkbox">
                        <input type="checkbox" checked="@IsChecked(category)"
                               @onchange="() => ToggleCategory(category)" />
                        @category
                    </label>
                }
            }
        </div>

        <div class="filter-section">
            <h4>Price Range</h4>
            <label class="filter-field">
                Min
                <input type="number" @bind="minPrice" min="0" step="0.01" />
            </label>
            <label class="filter-field">
                Max
                <input type="number" @bind="maxPrice" min="0" step="0.01" />
            </label>
        </div>

        <div class="filter-section">
            <label class="filter-checkbox">
                <input type="checkbox" @bind="inStockOnly" />
                In Stock Only
            </label>
        </div>

        <div class="filter-actions">
            <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    <main class="catalog-main">
        @if (errorMessage is not null)
        {
            <div class="catalog-error">
                <p>Something went wrong: @errorMessage</p>
                <button class="btn btn-primary" @onclick="ApplyFilters">Retry</button>
            </div>
        }
        else if (isLoading)
        {
            <div class="catalog-loading">
                <p>Loading products...</p>
            </div>
        }
        else if (result is null || result.Items.Count == 0)
        {
            <div class="catalog-empty">
                <p>No products found matching your criteria.</p>
            </div>
        }
        else
        {
            <div class="catalog-toolbar">
                <select @bind="sortBy" @bind:after="ApplyFilters">
                    <option value="price_asc">Price: Low to High</option>
                    <option value="price_desc">Price: High to Low</option>
                    <option value="name_asc">Name: A-Z</option>
                    <option value="rating_desc">Rating: Highest</option>
                </select>
                <span class="catalog-showing">
                    Showing @(((result.Page - 1) * result.PageSize) + 1)–@(Math.Min(result.Page * result.PageSize, result.TotalCount)) of @result.TotalCount products
                </span>
            </div>

            <div class="product-grid">
                @foreach (var product in result.Items)
                {
                    <ProductCard @key="product.Id" Product="product"
                                 OnProductSelected="HandleProductSelected"
                                 OnAddToCart="HandleAddToCart" />
                }
            </div>

            <div class="catalog-pagination">
                <button class="btn" disabled="@(currentPage <= 1)" @onclick="PreviousPage">Previous</button>
                @for (int i = 1; i <= totalPages; i++)
                {
                    var pageNum = i;
                    <button class="btn @(pageNum == currentPage ? "btn-active" : "")"
                            @onclick="() => GoToPage(pageNum)">@pageNum</button>
                }
                <button class="btn" disabled="@(currentPage >= totalPages)" @onclick="NextPage">Next</button>
            </div>
        }
    </main>
</div>

@code {
    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;
    private int totalPages;

    private PagedResult<Product>? result;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
            await LoadProducts();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
            isLoading = false;
        }
    }

    private async Task LoadProducts()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            result = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
            totalPages = (int)Math.Ceiling((double)result.TotalCount / PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private bool IsChecked(string category) => selectedCategories.Contains(category);

    private void ToggleCategory(string category)
    {
        if (!selectedCategories.Remove(category))
        {
            selectedCategories.Add(category);
        }
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task GoToPage(int page)
    {
        currentPage = page;
        await LoadProducts();
    }

    private async Task PreviousPage() => await GoToPage(currentPage - 1);
    private async Task NextPage() => await GoToPage(currentPage + 1);

    private void HandleProductSelected(Product product)
    {
        // Parent page handles navigation to detail page
    }

    private void HandleAddToCart(Product product)
    {
        // Handle add to cart logic
    }
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

.catalog-sidebar {
    width: 25%;
    min-width: 200px;
}

.catalog-sidebar h3 {
    margin-top: 0;
}

.catalog-main {
    width: 75%;
}

.filter-section {
    margin-bottom: 1.5rem;
}

.filter-section h4 {
    margin-bottom: 0.5rem;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.25rem;
    cursor: pointer;
}

.filter-field {
    display: flex;
    flex-direction: column;
    margin-bottom: 0.5rem;
}

.filter-field input {
    padding: 0.25rem 0.5rem;
    margin-top: 0.25rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn {
    padding: 0.5rem 1rem;
    border: 1px solid #ccc;
    background: #fff;
    cursor: pointer;
    border-radius: 4px;
}

.btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

.btn-secondary {
    background: #6c757d;
    color: #fff;
    border-color: #6c757d;
}

.btn-active {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

.catalog-toolbar {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1rem;
}

.catalog-toolbar select {
    padding: 0.4rem 0.75rem;
}

.catalog-showing {
    margin-left: auto;
    color: #666;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1rem;
    margin-bottom: 1.5rem;
}

.catalog-pagination {
    display: flex;
    gap: 0.5rem;
    justify-content: center;
    flex-wrap: wrap;
}

.catalog-loading,
.catalog-empty,
.catalog-error {
    text-align: center;
    padding: 3rem 1rem;
    color: #666;
}

.catalog-error {
    color: #dc3545;
}

@using sv_036148edf6b541d49e20ea38f5745826.Services

<div class="product-card" @onclick="() => OnProductSelected.InvokeAsync(Product)">
    <div class="product-image" title="@Product.Name">
        @Product.Name
    </div>
    <div class="product-info">
        <h4 class="product-name">@Product.Name</h4>
        <p class="product-price">@Product.Price.ToString("C")</p>
        <span class="product-rating">@GetStarRating(Product.Rating)</span>
        @if (!Product.InStock)
        {
            <span class="out-of-stock-badge">Out of Stock</span>
        }
        <button class="btn btn-add-cart"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Product Product { get; set; } = default!;
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }
    [Parameter] public EventCallback<Product> OnAddToCart { get; set; }

    private static string GetStarRating(double rating)
    {
        int filled = (int)Math.Round(rating);
        return new string('★', filled) + new string('☆', 5 - filled);
    }

    private async Task HandleAddToCart()
    {
        await OnAddToCart.InvokeAsync(Product);
    }
}

.product-card {
    border: 1px solid #ddd;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.product-image {
    background: #f0f0f0;
    height: 160px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 0.9rem;
    padding: 1rem;
    text-align: center;
}

.product-info {
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    flex: 1;
}

.product-name {
    margin: 0;
    font-size: 1rem;
}

.product-price {
    margin: 0;
    font-weight: bold;
    color: #333;
}

.product-rating {
    color: #f5a623;
}

.out-of-stock-badge {
    display: inline-block;
    background: #dc3545;
    color: #fff;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    width: fit-content;
}

.btn-add-cart {
    margin-top: auto;
    padding: 0.4rem 0.75rem;
    background: #198754;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-add-cart:disabled {
    background: #ccc;
    cursor: not-allowed;
}

@page "/catalog"
