+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private bool IsChecked(string category) => selectedCategories.Contains(category);
+
+    private void ToggleCategory(string category)
+    {
+        if (!selectedCategories.Remove(category))
+        {
+            selectedCategories.Add(category);
+        }
+    }
+
+    private async Task ApplyFilters()
+    {
+        currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task ClearFilters()
+    {
+        selectedCategories.Clear();
+        minPrice = null;
+        maxPrice = null;
+        inStockOnly = false;
+        currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task GoToPage(int page)
+    {
+        currentPage = page;
+        await LoadProducts();
+    }
+
+    private async Task PreviousPage() => await GoToPage(currentPage - 1);
+    private async Task NextPage() => await GoToPage(currentPage + 1);
+
+    private void HandleProductSelected(Product product)
+    {
+        // Parent page handles navigation to detail page
+    }
+
+    private void HandleAddToCart(Product product)
+    {
+        // Handle add to cart logic
+    }
+}
