@using sv_036148edf6b541d49e20ea38f5745826.Services

<div class="product-card" @onclick="() => OnProductSelected.InvokeAsync(Product)">
    <div class="product-image" title="@Product.Name">
        @Product.Name
    </div>
    <div class="product-info">
        <h4 class="product-name">@Product.Name</h4>
        <p class="product-price">@Product.Price.ToString("C")</p>
        <span class="product-rating">@GetStarRating(Product.Rating)</span>
        @if (!Product.InStock)
        {
            <span class="out-of-stock-badge">Out of Stock</span>
        }
        <button class="btn btn-add-cart"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Product Product { get; set; } = default!;
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }
    [Parameter] public EventCallback<Product> OnAddToCart { get; set; }

    private static string GetStarRating(double rating)
    {
        int filled = (int)Math.Round(rating);
        return new string('★', filled) + new string('☆', 5 - filled);
    }

    private async Task HandleAddToCart()
    {
        await OnAddToCart.InvokeAsync(Product);
    }
}

