toolArgs.file_text:
.product-card {
    border: 1px solid #ddd;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.product-image {
    background: #f0f0f0;
    height: 160px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 0.9rem;
    padding: 1rem;
    text-align: center;
}

.product-info {
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    flex: 1;
}

.product-name {
    margin: 0;
    font-size: 1rem;
}

.product-price {
    margin: 0;
    font-weight: bold;
    color: #333;
}

.product-rating {
    color: #f5a623;
}

.out-of-stock-badge {
    display: inline-block;
    background: #dc3545;
    color: #fff;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    width: fit-content;
}

.btn-add-cart {
    margin-top: auto;
    padding: 0.4rem 0.75rem;
    background: #198754;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-add-cart:disabled {
    background: #ccc;
    cursor: not-allowed;
}

